import React from "react";
import VoiceButton from "./VoiceButton";

const Message = ({ text, type }) => {
  return (
    <div className={`message ${type}`}>
      <p>{text}</p>
      {type === "bot" && <VoiceButton text={text} />} {/* Voice output for bot responses */}
    </div>
  );
};

export default Message;
